item.command:
/bin/bash -lc "python - <<'PY'
import json,os
for f in ['input.json','output.schema.json','primary-source-manifest.json','exam-hh-motion-laws-from-rest.goal.json','exam-sn-energy-conservation.goal.json']:
 d=json.load(open(f)); print(f,os.stat(f).st_size)
 print(list(d.keys()))
 if f=='input.json':
  for k,v in d.items(): print(k, type(v).__name__, len(v) if isinstance(v,(list,dict,str)) else v)
 else:
  if f in ['output.schema.json','primary-source-manifest.json']: print(json.dumps(d,ensure_ascii=False,indent=2))
PY"

